// Downloads the test media listed in tests/media/manifest.json (generated by
// scripts/make-test-media.mjs) and tests/media/speech.json (the caption test set,
// from scripts/make-speech-media.mjs) into tests/media/, verifying each SHA-256.
// Files already present with the right hash are skipped. Media never goes into git.
import { createHash } from 'node:crypto';
import { existsSync } from 'node:fs';
import { readFile, rename, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { root } from './lib.mjs';

const mediaDir = join(root, 'tests/media');
const manifests = await Promise.all(
  ['manifest.json', 'speech.json']
    .filter((name) => existsSync(join(mediaDir, name)))
    .map(async (name) => JSON.parse(await readFile(join(mediaDir, name), 'utf8'))),
);
const manifest = {
  release: manifests.map((m) => m.release).join(', '),
  files: manifests.flatMap((m) => m.files),
};
const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');

let fetched = 0;
for (const entry of manifest.files) {
  if (basename(entry.file) !== entry.file)
    throw new Error('Test media names must be plain file names: ' + entry.file);
  const path = join(mediaDir, entry.file);
  if (existsSync(path) && sha256(await readFile(path)) === entry.sha256) continue;
  const response = await fetch(entry.url);
  if (!response.ok) throw new Error('Download failed: ' + response.status + ' ' + entry.url);
  const bytes = Buffer.from(await response.arrayBuffer());
  const actual = sha256(bytes);
  if (actual !== entry.sha256)
    throw new Error(entry.file + ' has SHA-256 ' + actual + ', expected ' + entry.sha256);
  await writeFile(path + '.part', bytes);
  await rename(path + '.part', path);
  fetched++;
}
console.log(
  `${manifest.files.length} test media files (${manifest.release}): ${fetched} fetched, ` +
    `${manifest.files.length - fetched} already present.`,
);
